import numpy as np,pandas as pd
W=Path(__file__).resolve().parent;sys.path.insert(0,str(W));import diagnose as d
O=d.O;m=d.m
os.environ.setdefault('MPLCONFIGDIR',str(W/'matplotlib_cache'))
