def table(x):return x.to_html(index=False,border=0,float_format=lambda v:f'{v:.4f}',na_rep='—')
def main():
 d.check();assert d.read(O/'trajectories_completion.json')['status']=='complete' and d.read(O/'branches_completion.json')['status']=='complete';hist=[];summary=[];branch=[];branchtrials=[];pred_rows=0;prefix=0;gradient=[]
 for cp in sorted((W/'trajectories').glob('fold_*/*/*/completion.json')):
  c=d.read(cp);assert c['binding']==d.binding()
  for p,h in c['hashes'].items():assert d.sha(p)==h
  if c['original_prefix_replay']=='PASS':prefix+=1
  records=d.read(cp.parent/'history.json');hist.extend(records);probes=[r for r in records if 'fresh_Ridge_valid_F1' in r];a=pd.DataFrame(probes).sort_values('epoch');fi=int(a.fold.iloc[0]);arm=a.arm.iloc[0];mode=a.head_mode.iloc[0];old=d.read(m.W/f'fold_{fi}/seed_42'/arm/'beta_0.1.json');oldscore=old['fresh_ridge']['valid_macro_f1'];head=a.sort_values(['head_valid_F1','epoch'],ascending=[False,True]).iloc[0];best=a.sort_values(['fresh_Ridge_valid_F1','epoch'],ascending=[False,True]).iloc[0];before=a[a.epoch<=old['last_epoch']];beforebest=before.sort_values(['fresh_Ridge_valid_F1','epoch'],ascending=[False,True]).iloc[0];initial=a[a.epoch==0].iloc[0]
  for r in probes:
   z=np.load(cp.parent/f"epoch_{r['epoch']}_VALID.npz");y=z['labels'];assert np.isfinite(z['Ridge_scores']).all() and np.isfinite(z['head_scores']).all();assert abs(m.metrics(y,z['Ridge_scores'].argmax(1))['macro_f1']-r['fresh_Ridge_valid_F1'])<1e-12;assert abs(m.metrics(y,z['head_scores'].argmax(1))['macro_f1']-r['head_valid_F1'])<1e-12;pred_rows+=len(y);gradient.append({'fold':fi,'arm':arm,'head_mode':mode,'epoch':r['epoch'],**r['gradient_diagnostic']})
  linear=d.read(cp.parent/'linear_reparameterization.json')
  summary.append({'fold':fi,'valid_donor':a.valid_donor.iloc[0],'arm':arm,'head_mode':mode,'old_best_epoch':old['best_epoch'],'old_stopping_epoch':old['last_epoch'],'old_Ridge_valid_F1':oldscore,'identity_Ridge_valid_F1':initial['identity_Ridge_valid_F1'],'probed_head_selected_epoch':int(head.epoch),'probed_head_selected_Ridge_F1':head.fresh_Ridge_valid_F1,'probed_Ridge_selected_epoch':int(best.epoch),'best_probed_Ridge_valid_F1':best.fresh_Ridge_valid_F1,'best_probed_gain_pp':100*(best.fresh_Ridge_valid_F1-initial.identity_Ridge_valid_F1),'selector_gap_pp':100*(best.fresh_Ridge_valid_F1-head.fresh_Ridge_valid_F1),'best_before_original_stop_epoch':int(beforebest.epoch),'best_before_original_stop_gain_vs_old_pp':100*(beforebest.fresh_Ridge_valid_F1-oldscore),'best_any_gain_vs_old_pp':100*(best.fresh_Ridge_valid_F1-oldscore),'last_raw_relative_norm':a.iloc[-1].relative_raw_norm,'last_centered_relative_norm':a.iloc[-1].relative_centered_norm,'last_whitened_relative_norm':a.iloc[-1].relative_whitened_norm,'last_max_abs_gate':a.iloc[-1].max_abs_gate,'last_saturated_fraction':a.iloc[-1].saturated_fraction,'VALID_delta_linear_Q2':linear['VALID_delta_Q2_vs_TRAIN_delta_mean']})
 for cp in sorted((W/'branches').glob('fold_*/*/completion.json')):
  c=d.read(cp);assert c['binding']==d.binding()
  for p,h in c['hashes'].items():assert d.sha(p)==h
  s=d.read(cp.parent/'selection.json');trials=d.read(cp.parent/'trials.json');best=s['identity_VALID_F1'];eta=None;alpha=d.read(cp.parent/'identity.json')['alpha']
  for t in trials:
   assert t['normal_equation_error']<1e-7;z=np.load(cp.parent/f"eta_{t['eta']}_alpha_{t['alpha']}_VALID.npz");assert np.isfinite(z['scores']).all();assert abs(m.metrics(z['labels'],z['scores'].argmax(1))['macro_f1']-t['VALID_F1'])<1e-12;pred_rows+=len(z['labels'])
   if t['VALID_F1']>best+1e-12:best=t['VALID_F1'];eta=t['eta'];alpha=t['alpha']
  assert eta==s['selected_eta'] and alpha==s['selected_alpha'] and abs(best-s['best_VALID_F1'])<1e-12
  branch.append(s|{'gain_pp':100*(best-s['identity_VALID_F1'])});branchtrials.extend(trials)
 assert len(summary)==24 and len(branch)==12 and prefix==12 and len(branchtrials)==396
 h=pd.DataFrame(hist);s=pd.DataFrame(summary);b=pd.DataFrame(branch);g=pd.DataFrame(gradient);h.to_csv(O/'trajectory_full_history.csv',index=False);h.dropna(subset=['fresh_Ridge_valid_F1']).to_csv(O/'trajectory_probes.csv',index=False);s.to_csv(O/'trajectory_summary.csv',index=False);b.to_csv(O/'conditional_readout_summary.csv',index=False);pd.DataFrame(branchtrials).to_csv(O/'conditional_readout_trials.csv',index=False);g.to_csv(O/'gradient_diagnostics.csv',index=False)
 paired=s.pivot(index=['fold','arm'],columns='head_mode',values='best_probed_gain_pp');paired['frozen_minus_joint_pp']=paired.frozen-paired.joint;paired.reset_index().to_csv(O/'head_freezing_comparison.csv',index=False)
 aggregate=s.groupby(['arm','head_mode'],sort=False).agg(mean_best_VALID_gain_pp=('best_probed_gain_pp','mean'),mean_selector_gap_pp=('selector_gap_pp','mean'),selector_gap_positive_folds=('selector_gap_pp',lambda v:int((v>1e-9).sum())),before_stop_better_than_original_joint_folds=('best_before_original_stop_gain_vs_old_pp',lambda v:int((v>1e-9).sum())),mean_raw_residual=('last_raw_relative_norm','mean'),mean_whitened_residual=('last_whitened_relative_norm','mean'),mean_linear_Q2=('VALID_delta_linear_Q2','mean')).reset_index();aggregate.to_csv(O/'diagnostic_summary.csv',index=False)
 support=d.read(m.O/'CLASS_LABELS.json');d.save(O/'CLASS_LABELS.json',support);original=d.read(O/'gate_rejection_funnel.json');counts={k:sum(x['rejection_stage']==k for x in original) for k in ['checkpoint_epoch0','fresh_Ridge','retained']};histold=pd.read_csv(O/'historical_candidate_diagnostics.csv');beta0=histold[(histold.arm=='gate')&(histold.beta==0)]
 data={'historical_gate_funnel':counts,'gate_candidates_epoch0':int(((histold.arm=='gate')&(histold.best_epoch==0)).sum()),'gate_beta0_positive_Ridge_candidates':int((beta0.ridge_delta_pp>1e-9).sum()),'gate_beta0_candidates':len(beta0),'trajectory_completions':24,'original_joint_prefix_replays':12,'conditional_readout_fits':396,'trajectory_epoch_records':len(hist),'VALID_score_rows_rechecked':pred_rows,'no_TEST_or_PBMC_scoring':True,'scope':'posthoc validation-only diagnostic; validation maxima are selected and optimistic, not held-out improvement'};d.save(O/'diagnosis_facts.json',data);d.save(O/'verification.json',{'status':'PASS',**data,'source_and_output_hashes_unchanged':True})
 fig,axs=plt.subplots(1,2,figsize=(14,5.7));jj=h[(h.arm=='gate')&h.fresh_Ridge_valid_F1.notna()].copy();jj['delta']=100*(jj.fresh_Ridge_valid_F1-jj.identity_Ridge_valid_F1)
 for mode,c in [('joint','#287e85'),('frozen','#ad7f3a')]:
  even=jj[(jj.head_mode==mode)&(jj.epoch%2==0)];curve=even.groupby('epoch').delta.mean();axs[0].plot(curve.index,curve.values,label=mode+' CE head',c=c)
 axs[0].axhline(0,c='#888',lw=.8);axs[0].set_xlabel('Training epoch (no early stopping)');axs[0].set_ylabel('VALID fresh Ridge change (percentage points)');axs[0].set_title('Same SAE gate; six validation-donor mean');axs[0].legend()
 pivot=b.pivot(index='valid_donor',columns='latent',values='gain_pp');yy=np.arange(len(pivot));axs[1].bar(yy-.18,pivot.learned_SAE,width=.35,color='#287e85',label='Learned SAE');axs[1].bar(yy+.18,pivot.random_TopK,width=.35,color='#9b9eaa',label='Random TopK');axs[1].set_xticks(yy,[v.replace('patient_','') for v in pivot.index]);axs[1].set_xlabel('Validation donor');axs[1].set_ylabel('Selected VALID gain (percentage points)');axs[1].set_title('Expanded readout: VALID-selected maxima');axs[1].legend();fig.tight_layout();fig.savefig(O/'diagnosis.png',dpi=170);plt.close(fig)
 audit='pending'
 if (O/'EXPERIMENT_AUDIT.json').exists():audit=str(d.read(O/'EXPERIMENT_AUDIT.json').get('verdict','see audit'))
 methods='''原主实验和归档不修改。本轮为看到先前TEST结果后提出的解释性诊断，仅计算六个历史TRAIN/VALID划分，SAE/训练种子固定42，绝不评分TEST或PBMC。原始Kang缓存含全部细胞，按既定供体掩码仅提取TRAIN/VALID；SAE缓存也只读这两种角色。训练头按类均匀并在类内平衡供体采样；最终Ridge按全局类别平衡但类内细胞等权，两者目标与权重不同。该差异不是数据泄漏，但也未被单因素隔离成性能损失的原因。
固定40轮门控轨迹：正确/正交旋转字典×联合训练/冻结同一初始CE头，beta0.1、lr0.001、原采样与clip5不变。每2轮及原best/stop轮重新拟合TRAIN Ridge，以VALID选择alpha；原历史前缀VALID F1一致，原选中检查点逐张量完全一致，没有原始全部前缀状态可供逐张量比较。比较head规则和Ridge规则时限同一组探测checkpoint。图中的固定epoch均值不选峰；selector_gap和best指标都是同一VALID上最大化的探索性上界，有多次比较及选择乐观性，不能当新的泛化收益。冻结头与联合训练的对照只改变该头是否更新，未检验其他学习率、采样或训练目标。
条件读出为[TRAIN标准化h, eta×TRAIN标准化z]的扩展线性分类器，eta=0.01/0.1/1，11个Ridge alpha，含identity并优先平局。eta后不再标准化，否则会消除分支正则差异。它有最多2560个输入坐标，不能等同于2048参数门控残差。随机TopK对照匹配名义字典维度2048/K32及正则搜索预算，但不匹配激活频率、相关性或实际非恒定特征数量。其最佳VALID表现不等于独立测试提升，也不能单独证明SAE语义特异优势；本轮未证明SAE特征有用或无用。
输入raw范数主要含共有均值，约为中心化范数的7倍；故同时报告中心化和标准化后的残差相对范数。历史max_batch_RMS_relative_residual指最大批次RMS比例，不是单细胞最大值。惩罚损失小不必然说明梯度小，本轮在同一个固定、按原规则采样的TRAIN批次上记录CE和惩罚对theta的梯度范数，不能代表所有批次。线性Q2为TRAIN拟合线性映射预测VALID修正量的诊断，alpha固定1；高Q2不构成全局线性、可逆或无信息损失证明。before_stop_better_than_original_joint_folds对joint可用于计算原轨迹漏选，对frozen只是新冻结头轨迹相对原joint的比较，不能称原历史轨迹遗漏。所有固定8类F1均保留缺失类别计0规则；VALID类别支持数另存，历史metadata的排除类型字段不代表当前8类实际组成。
数值告警被保留于阶段warnings.json，源文件/模型/预测hash、全部保存VALID分数与指标重算通过；同模型家族独立审查仍为provisional。诊断不支持把阴性结果归因于单一机制，也不支持根据这些VALID最大值宣布新性能结果。
'''
 text='SAE残差未保留的原因诊断\n\n历史淘汰漏斗：'+json.dumps(counts,ensure_ascii=False)+'\n\n轨迹诊断：\n'+aggregate.to_string(index=False)+'\n\n条件读出（VALID选择）：\n'+b[['fold','valid_donor','latent','gain_pp','selected_eta','identity_selected']].to_string(index=False)+'\n\n方法与边界：\n'+methods+f'\n数值核验PASS；独立审查{audit}。\n';(O/'RESULTS_ZH.txt').write_text(text)
 body='<h1>为什么SAE残差大多没有被保留？</h1><p>仅TRAIN/VALID诊断；不产生新的TEST性能结论。</p><section><h2>原始淘汰位置</h2>'+table(pd.DataFrame([counts]))+'</section><section><h2>固定长度训练与条件读出</h2><img src="data:image/png;base64,'+base64.b64encode((O/'diagnosis.png').read_bytes()).decode()+'"></section><section><h2>选型与轨迹诊断</h2>'+table(aggregate)+'</section><section><h2>逐划分轨迹</h2>'+table(s)+'</section><section><h2>条件读出：扩展分类器的验证结果</h2>'+table(b[['fold','valid_donor','latent','identity_VALID_F1','best_VALID_F1','gain_pp','selected_eta','identity_selected']])+'</section><section><h2>方法与边界</h2><p>'+html.escape(methods).replace('\n','<br>')+f'</p><p>数值核验PASS；科研审查{html.escape(audit)}，same-family/provisional。</p></section><section><h2>文件</h2><ul>'+''.join(f'<li><a href="{p.name}">{p.name}</a></li>' for p in sorted(O.iterdir()) if p.is_file() and p.suffix in ['.csv','.json','.md','.txt'])+'</ul></section>'
 css='body{font-family:-apple-system,sans-serif;background:#f2f5f5;color:#223e44;line-height:1.7}main{max-width:1300px;margin:30px auto;padding:0 20px}section{background:white;padding:22px;border-radius:12px;margin:20px 0;overflow:auto}table{border-collapse:collapse;font-size:13px}th,td{padding:8px;border-bottom:1px solid #d9e3e3;text-align:left}th{background:#edf3f3}img{width:100%;height:auto}a{color:#237a7a}'
 (O/'REPORT.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SAE残差失败诊断</title><style>'+css+'</style><main>'+body+'</main></html>');d.save(O/'EXPERIMENT_TRACKER.json',{'status':'awaiting_review' if audit=='pending' else 'complete','trajectories':'complete','conditional_readouts':'complete','numerical_verification':'PASS','scientific_review':audit,'scored_roles':['train','valid']});print('DIAGNOSIS_REPORT_COMPLETE',flush=True)
if __name__=='__main__':main()
